// ---------------------------------------------------------------------------------------------------------------------
// Blocks and chapters

export type Block =
  | { kind: 'p'; text: LocalizedText }
  | { kind: 'h'; text: LocalizedText }
  | { kind: 'steps'; title?: LocalizedText; items: LocalizedText[] }
  | { kind: 'list'; items: LocalizedText[] }
  | { kind: 'table'; caption?: LocalizedText; head: LocalizedText[]; rows: LocalizedText[][] }
  | { kind: 'note' | 'tip' | 'warning'; text: LocalizedText }
  | { kind: 'feature'; feature: FeatureKey }
  | { kind: 'formula'; formula: string; text: LocalizedText }
  | { kind: 'example'; title: LocalizedText; steps: LocalizedText[]; expect: LocalizedText }
  | { kind: 'link'; chapter: string; text: LocalizedText }
  | { kind: 'controls' };

export interface Chapter {
  id: string;
  title: LocalizedText;
  summary: LocalizedText;
  /** Search keywords (both languages). */
  tags: string[];
  blocks: Block[];
}

const C = (row: [string, string][]): LocalizedText[] => row.map(([en, ru]) => L(en, ru));
const same = (s: string): LocalizedText => L(s, s);

