// Chapters generated from the catalogue index (the same data the catalogue shows), so the guide never drifts from the data.

const KIND_TITLES: Record<string, LocalizedText> = CATALOG_INDEX.labels.sceneKinds;

function worldGuide(): Chapter {
  const blocks: Block[] = [
    { kind: 'p', text: L(
      `Every world in the catalogue, by kind: its group, number of bodies at start, and a short description. The letter A or D is the catalogue’s preparation label; every world runs as N-body dynamics.`,
      `Все миры каталога по видам: группа, число тел на старте и краткое описание. Буква A или D — пометка подготовки в каталоге; любой мир рассчитывается как динамика N тел.`) },
  ];
  for (const kind of ['solar', 'real_planetary', 'real_stellar_or_compact', 'authored_procedural']) {
    const scenes = CATALOG_INDEX.scenes.filter((x) => x.kind === kind);
    if (!scenes.length) continue;
    const label = KIND_TITLES[kind] ?? same(kind);
    blocks.push({ kind: 'h', text: L(`${label.en} (${scenes.length})`, `${label.ru} (${scenes.length})`) });
    blocks.push({ kind: 'table', head: C([['World', 'Мир'], ['Group', 'Группа'], ['Bodies', 'Тела'], ['Label', 'Пометка'], ['About', 'Описание']]), rows: scenes.map((x) => [
      x.name, x.groupLabel, same(String(x.bodyCount) + (x.optionalCount ? ` (+${x.optionalCount})` : '')), same(x.physicsMode), x.description,
    ]) });
  }
  blocks.push({ kind: 'note', text: L(
    `“+N” counts optional bodies (for example candidates or disputed planets) that the world can include but does not start with.`,
    `«+N» — необязательные тела (например, кандидаты или спорные планеты), которые мир может включить, но не содержит на старте.`) });
  return {
    id: 'world-guide',
    title: L('Guide to all 40 worlds', 'Путеводитель по 40 мирам'),
    summary: L('Every world with its group, body count and description.', 'Каждый мир с группой, числом тел и описанием.'),
    tags: ['worlds', 'list', 'guide', 'systems', 'миры', 'список', 'путеводитель', 'системы'],
    blocks,
  };
}

function learningGuide(): Chapter {
  const sceneName = (id: string): LocalizedText => CATALOG_INDEX.scenes.find((x) => x.id === id)?.name ?? same(id);
  return {
    id: 'learning-guide',
    title: L('List of lessons and experiments', 'Список уроков и экспериментов'),
    summary: L('All 24 lessons and 72 experiments with their worlds.', 'Все 24 урока и 72 эксперимента с их мирами.'),
    tags: ['lessons', 'experiments', 'list', 'уроки', 'эксперименты', 'список'],
    blocks: [
      { kind: 'feature', feature: 'lessons' },
      { kind: 'table', caption: L('Lessons', 'Уроки'), head: C([['Id', 'Код'], ['Lesson', 'Урок'], ['Goal', 'Цель'], ['World', 'Мир'], ['Steps', 'Шаги']]), rows: CATALOG_INDEX.lessons.map((x) => [
        same(x.id), x.title, x.goal, sceneName(x.sceneId), same(String(x.stepCount)),
      ]) },
      { kind: 'feature', feature: 'experiments' },
      { kind: 'table', caption: L('Experiments', 'Эксперименты'), head: C([['Id', 'Код'], ['Experiment', 'Эксперимент'], ['Question', 'Вопрос'], ['World', 'Мир']]), rows: CATALOG_INDEX.experiments.map((x) => [
        same(x.id), x.title, x.question, sceneName(x.sceneId),
      ]) },
      { kind: 'tip', text: L(
        `Many experiments need only the inspector and time controls: open the world, make the change the question describes, run time and compare.`,
        `Многим экспериментам нужны только свойства и управление временем: откройте мир, внесите изменение из вопроса, запустите время и сравните.`) },
    ],
  };
}

