function fmtDistanceKpc(kpc: number, lang: Lang): string {
  const ly = kpc * 3261.56;
  const n = (x: number, d = 3) => new Intl.NumberFormat(lang === 'ru' ? 'ru-RU' : 'en-US', { maximumSignificantDigits: d }).format(x);
  if (kpc < 1000) return `${n(kpc)} ${lang === 'ru' ? 'кпк' : 'kpc'} (${ly >= 1e6 ? n(ly / 1e6, 2) + (lang === 'ru' ? ' млн св. лет' : ' million ly') : n(ly / 1000, 3) + (lang === 'ru' ? ' тыс. св. лет' : ' thousand ly')})`;
  return `${n(kpc / 1000)} ${lang === 'ru' ? 'Мпк' : 'Mpc'} (${n(ly / 1e6, 3)} ${lang === 'ru' ? 'млн св. лет' : 'million ly'})`;
}

function galaxyAtlasChapter(): Chapter {
  const dist = (g: (typeof COSMOS_GALAXIES)[number]): LocalizedText => {
    if (g.id === 'milky_way') return L('we are inside (centre 8.1 kpc away)', 'мы внутри (центр в 8,1 кпк)');
    const d = g.distanceKpc;
    const pm = d.errMinus != null && d.errPlus != null ? Math.max(d.errMinus, d.errPlus) : d.err ?? null;
    const add = (lang: Lang) => (pm ? ` ±${new Intl.NumberFormat(lang === 'ru' ? 'ru-RU' : 'en-US', { maximumSignificantDigits: 2 }).format((pm / d.value) * 100)} %` : '');
    return L(fmtDistanceKpc(d.value, 'en') + add('en'), fmtDistanceKpc(d.value, 'ru') + add('ru'));
  };
  const size = (g: (typeof COSMOS_GALAXIES)[number]): LocalizedText =>
    g.diameterKpc ? L(`${new Intl.NumberFormat('en-US', { maximumSignificantDigits: 2 }).format(g.diameterKpc)} kpc`, `${new Intl.NumberFormat('ru-RU', { maximumSignificantDigits: 2 }).format(g.diameterKpc)} кпк`) : same('—');
  const blocks: Block[] = [
    { kind: 'p', text: L(
      `The ${COSMOS_GALAXIES.length} galaxies on the map, region by region, with their catalogue type, distance and size. Distances are from NASA/IPAC NED (the median of published redshift-independent estimates; ± is their spread) or, where those scatter widely or are few, from the Updated Nearby Galaxy Catalog or NED with an assumed ±10–15 %. Sizes are catalogue isophotal diameters converted at that distance.`,
      `${COSMOS_GALAXIES.length} галактик на карте по областям с их каталожным типом, расстоянием и размером. Расстояния — из NASA/IPAC NED (медиана опубликованных оценок, не зависящих от красного смещения; ± — их разброс) или, где оценки сильно расходятся либо их мало, из обновлённого каталога близких галактик или NED с принятыми ±10–15 %. Размеры — каталожные изофотные диаметры, пересчитанные на это расстояние.`) },
    { kind: 'note', text: REGIONS_NOTE },
  ];
  const byId = new Map(COSMOS_GALAXIES.map((g) => [g.id, g]));
  for (const rid of REGION_ORDER) {
    const r = COSMOS_REGIONS.find((x) => x.id === rid)!;
    const list = r.directMembers.map((id) => byId.get(id)).filter((g): g is (typeof COSMOS_GALAXIES)[number] => !!g);
    if (!list.length) continue;
    blocks.push({ kind: 'h', text: L(`${r.name.en} · ${ASSOCIATION_LABELS[r.association].label.en}`, `${r.name.ru} · ${ASSOCIATION_LABELS[r.association].label.ru}`) });
    blocks.push({ kind: 'p', text: L(`${r.description.en} ${r.associationNote.en}`, `${r.description.ru} ${r.associationNote.ru}`) });
    blocks.push({ kind: 'table', head: C([['Galaxy', 'Галактика'], ['Type', 'Тип'], ['Distance', 'Расстояние'], ['Diameter', 'Диаметр'], ['About', 'Описание']]), rows: list.map((g) => [
      g.name, L(`${g.morphology || '—'} · ${g.kindLabel.en}`, `${g.morphology || '—'} · ${g.kindLabel.ru}`), dist(g), size(g), g.description,
    ]) });
  }
  blocks.push({ kind: 'note', text: L(
    `Galaxy shapes and orientations on the map are approximate reconstructions; the stars inside them are a procedural model. The Milky Way is seen from inside, so its bar and arms come from star counts and models, not from a photograph.`,
    `Формы и ориентации галактик на карте — приближённые реконструкции; звёзды внутри — процедурная модель. Млечный Путь мы видим изнутри, поэтому его перемычка и рукава получены по подсчётам звёзд и моделям, а не по фотографии.`) });
  return {
    id: 'galaxy-atlas',
    title: L('Catalogue of galaxies', 'Каталог галактик'),
    summary: L('Every galaxy on the Universe map by region, with its type, distance and size.', 'Каждая галактика карты Вселенной по областям — с типом, расстоянием и размером.'),
    tags: ['galaxies', 'andromeda', 'magellanic', 'local group', 'm31', 'm33', 'virgo', 'fornax', 'coma', 'sombrero', 'cluster', 'group', 'галактики', 'андромеда', 'местная группа', 'магеллановы', 'дева', 'печь', 'сомбреро', 'скопление', 'группа'],
    blocks,
  };
}

