// Search

export interface HandbookHit {
  type: 'chapter' | 'glossary' | 'faq';
  id: string; // chapter id, glossary id, or 'faq:<index>'
  chapter?: string; // the chapter to open
  title: string;
  snippet: string;
  score: number;
}

function blockTexts(b: Block, lang: Lang): string[] {
  const t = (x: LocalizedText) => x[lang];
  switch (b.kind) {
    case 'p': case 'h': case 'note': case 'tip': case 'warning': return [t(b.text)];
    case 'steps': return [...(b.title ? [t(b.title)] : []), ...b.items.map(t)];
    case 'list': return b.items.map(t);
    case 'table': return [...(b.caption ? [t(b.caption)] : []), ...b.head.map(t), ...b.rows.flat().map(t)];
    case 'formula': return [b.formula, t(b.text)];
    case 'example': return [t(b.title), ...b.steps.map(t), t(b.expect)];
    case 'link': return [t(b.text)];
    case 'feature': return [t(FEATURE_STATUS[b.feature].name)];
    case 'controls': return CONTROLS.flatMap((c) => [t(c.action), c.keyboard ?? '', c.mouse ? t(c.mouse) : '', c.touch ? t(c.touch) : '']);
  }
}

/** Plain text of a chapter in one language (for search indexes or reading aloud). */
export function chapterText(ch: Chapter, lang: Lang): string {
  return [ch.title[lang], ch.summary[lang], ...ch.blocks.flatMap((b) => blockTexts(b, lang))].join('\n');
}

const fold = (s: string) => s.toLowerCase().replace(/ё/g, 'е');

function snippetOf(text: string, word: string, width = 140): string {
  const i = fold(text).indexOf(word);
  if (i < 0) return text.slice(0, width);
  const start = Math.max(0, i - 40);
  return (start > 0 ? '…' : '') + text.slice(start, start + width).replace(/\s+/g, ' ') + (start + width < text.length ? '…' : '');
}

/** Ranked search over chapters, glossary and FAQ in one language. Every query word must occur. */
export function searchHandbook(query: string, lang: Lang, limit = 20): HandbookHit[] {
  const words = fold(query).split(/\s+/).filter((w) => w.length > 1);
  if (!words.length) return [];
  const hits: HandbookHit[] = [];
  const rank = (title: string, body: string, tags = ''): number => {
    const ft = fold(title), fb = fold(body), fg = fold(tags);
    let s = 0;
    for (const w of words) {
      const inTitle = ft.includes(w), inTags = fg.includes(w), inBody = fb.includes(w);
      if (!inTitle && !inTags && !inBody) return 0;
      s += (inTitle ? 5 : 0) + (inTags ? 3 : 0) + (inBody ? 1 : 0);
    }
    return s;
  };
  for (const ch of CHAPTERS) {
    const body = chapterText(ch, lang);
    const s = rank(ch.title[lang], body, ch.tags.join(' '));
    if (s) hits.push({ type: 'chapter', id: ch.id, chapter: ch.id, title: ch.title[lang], snippet: snippetOf(body, words[0]), score: s });
  }
  for (const g of GLOSSARY) {
    const s = rank(g.term[lang], g.definition[lang]);
    if (s) hits.push({ type: 'glossary', id: g.id, chapter: g.chapter, title: g.term[lang], snippet: g.definition[lang], score: s + 1 });
  }
  FAQ.forEach((f, k) => {
    const s = rank(f.q[lang], f.a[lang]);
    if (s) hits.push({ type: 'faq', id: 'faq:' + k, chapter: f.chapter, title: f.q[lang], snippet: f.a[lang], score: s });
  });
  return hits.sort((a, b) => b.score - a.score).slice(0, limit);
}

